CREATE TABLE sales_import_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by text NOT NULL, platform text NOT NULL, file_name text NOT NULL, imported_at timestamptz NOT NULL DEFAULT now(), total_rows integer NOT NULL DEFAULT 0, imported_rows integer NOT NULL DEFAULT 0, duplicate_rows integer NOT NULL DEFAULT 0, unmatched_rows integer NOT NULL DEFAULT 0, error_rows integer NOT NULL DEFAULT 0, notes text)